package com.example.arrows

import android.content.Context
import kotlin.math.ceil
import kotlin.math.floor
import kotlin.math.max
import kotlin.math.roundToInt

/**
 * The 100 level silhouettes (horse, heart, fish, rocket ...) stored in assets/shapes.txt
 * (generated by tools/build_shapes.py). Each shape is a small bitmap that is re-sampled to the grid
 * size of the level.
 */
object ShapeLibrary {

    class Shape(val name: String, val minN: Int, val w: Int, val h: Int, val bits: Array<BooleanArray>)

    private var cache: List<Shape>? = null

    fun all(context: Context): List<Shape> =
        cache ?: synchronized(this) { cache ?: load(context).also { cache = it } }

    private fun load(context: Context): List<Shape> {
        val result = ArrayList<Shape>()
        context.applicationContext.assets.open("shapes.txt").bufferedReader().useLines { lines ->
            var name = ""
            var minN = 16
            var w = 0
            var h = 0
            var rows = ArrayList<BooleanArray>()
            fun flush() {
                if (name.isNotEmpty() && rows.isNotEmpty()) result.add(Shape(name, minN, w, h, rows.toTypedArray()))
            }
            for (line in lines) {
                if (line.startsWith("@")) {
                    flush()
                    // "@Pine tree 21 48 44"  ->  name, minN, w, h
                    val p = line.substring(1).trim().split(" ")
                    h = p[p.size - 1].toInt()
                    w = p[p.size - 2].toInt()
                    minN = p[p.size - 3].toInt()
                    name = p.subList(0, p.size - 3).joinToString(" ")
                    rows = ArrayList()
                } else if (line.isNotEmpty()) {
                    rows.add(BooleanArray(line.length) { line[it] == '#' })
                }
            }
            flush()
        }
        return result
    }

    /** Re-samples the shape so that its longer side is [n] cells. true = cell belongs to the shape. */
    fun sample(shape: Shape, n: Int): Array<BooleanArray> {
        val long = max(shape.w, shape.h).toFloat()
        val cols = max(1, (shape.w * n / long).roundToInt())
        val rows = max(1, (shape.h * n / long).roundToInt())
        val inside = Array(rows) { BooleanArray(cols) }
        for (gy in 0 until rows) {
            val y0 = floor(gy * shape.h / rows.toFloat()).toInt()
            val y1 = max(y0 + 1, ceil((gy + 1) * shape.h / rows.toFloat()).toInt()).coerceAtMost(shape.h)
            for (gx in 0 until cols) {
                val x0 = floor(gx * shape.w / cols.toFloat()).toInt()
                val x1 = max(x0 + 1, ceil((gx + 1) * shape.w / cols.toFloat()).toInt()).coerceAtMost(shape.w)
                var on = 0
                var total = 0
                for (y in y0 until y1) for (x in x0 until x1) {
                    total++
                    if (shape.bits[y][x]) on++
                }
                inside[gy][gx] = total > 0 && on * 2 >= total
            }
        }
        return largestComponent(inside)
    }

    /** Keeps only the biggest connected piece so the silhouette is one solid shape. */
    private fun largestComponent(m: Array<BooleanArray>): Array<BooleanArray> {
        val rows = m.size
        val cols = m[0].size
        val label = Array(rows) { IntArray(cols) }
        val dx = intArrayOf(1, -1, 0, 0)
        val dy = intArrayOf(0, 0, 1, -1)
        var best = 0
        var bestSize = 0
        var next = 0
        val queue = ArrayDeque<Int>()
        for (sy in 0 until rows) for (sx in 0 until cols) {
            if (!m[sy][sx] || label[sy][sx] != 0) continue
            next++
            var size = 0
            label[sy][sx] = next
            queue.add(sy * cols + sx)
            while (queue.isNotEmpty()) {
                val cur = queue.removeFirst()
                val cx = cur % cols
                val cy = cur / cols
                size++
                for (k in 0..3) {
                    val nx = cx + dx[k]
                    val ny = cy + dy[k]
                    if (nx in 0 until cols && ny in 0 until rows && m[ny][nx] && label[ny][nx] == 0) {
                        label[ny][nx] = next
                        queue.add(ny * cols + nx)
                    }
                }
            }
            if (size > bestSize) { bestSize = size; best = next }
        }
        return Array(rows) { y -> BooleanArray(cols) { x -> label[y][x] == best } }
    }
}
